                + step / route_name_cursor[ROUTE_NAME_COLOR_TO_STAR_COUNT]
                + 1].y_bits;
        route_slots[record_count].record.map_z_bits = 0;

        char missing_label[128];
        sprintf(missing_label, "LEVEL %i MISSING", record_count);
